#pragma once

// Replaceable input to AgentHost. Implementations may be deterministic and
// pump-driven or backed by an asynchronous network service, but they expose
// the same typed event stream. AgentHost remains the owner of conversation
// persistence and ToolExecutionCoordinator remains the only workspace
// execution path.

#include "AgentProtocol.hpp"
#include "ProjectStateDocument.hpp"
#include "ToolExecution.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <utility>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

struct AgentAttachmentContext
{
    std::string id;
    std::string name;
    std::string kind;
    std::string mime;
    std::string summary;
    std::string text;  // decoded UTF-8 context, size bounded by AgentHost
    std::string bytes; // image/PDF bytes, size bounded by AgentHost
    bool        importable{false};
};

struct AgentConversationContext
{
    std::string role; // user|assistant|developer; empty for a tool exchange
    std::string text;
    // A user message sent from a print-issue button: the app's JSON about the
    // issue, sent beside the person's words, never inside them.
    std::string issue_context;
    // A tool the model called in an earlier turn and what it got back, kept
    // as one entry so the call is never sent without its output. Set when
    // call_id is; role and text are then empty.
    std::string call_id;
    std::string tool;
    std::string arguments_json;
    std::string output_json;
};

// A project skill as its page wrote it (AgentUI/src/skills/<name>/SKILL.md).
// A skill with a trigger is added by the app when that event happens; one
// with a description is listed for the model to read with skill_read when
// it judges it useful. A skill may have both.
struct AgentSkill
{
    std::string name;
    std::string trigger;     // Protocol::SkillTrigger, or empty
    std::string description; // one line, or empty
    std::string text;
};

// A skill the app fired for one request because its event happened: the text
// goes in as the request's last item, after the picture that goes with it.
// Built when the request is and never stored in the conversation, so no later
// request carries it, not even the next one of the same turn.
struct AgentSkillUse
{
    std::string                      name;
    std::string                      text;
    std::shared_ptr<const ToolImage> picture;
    std::string                      trigger;
    // Triggers of skills this one gives way to: when one of them fires for
    // the same request, this one is left out of it.
    std::vector<std::string>         yields_to;
};

// What one conversation is for. The project conversation leaves the tools and
// workspace at their defaults (every in-app tool, the project workspace) and
// takes its instructions from its page; a session with its own subject (the
// temporary printer task chat) states its instructions and names the tools
// that belong to it.
struct AgentSessionProfile
{
    // The whole system prompt, written by the session's page; the project
    // assistant's comes from AgentUI/src/projectInstructions.ts.
    std::string              instructions;
    std::vector<std::string> tool_names;               // empty: every in-app tool
    bool                     include_workspace{true};  // the open project's state
    // The thread's notes reach the model as the app's own statements. Off
    // where the workspace is sent: there a note restates project state the
    // snapshot already carries, and a stale one would contradict it.
    bool                     notes_in_context{false};
};

struct AgentRequest
{
    enum class Purpose { Reply, ConversationTitle };
    Purpose                              purpose{Purpose::Reply};
    std::string                           request_id;
    std::string                           user_text;
    std::string                           issue_context; // see AgentConversationContext
    int                                   attempt{1};
    AgentSessionProfile                   session;
    Workspace::WorkspaceSnapshot          workspace;
    // The chat's own record of this print, sent with the workspace: the
    // purpose the person gave (the setup card's title and the intent fields)
    // and the plan the model pinned with plan_set.
    std::string                           setup_title;
    std::vector<IntentField>              intent;
    PlanRecord                            plan;
    // The presets or the plate type in force differ from those the model was
    // last asked to check against the recorded purpose.
    bool                                  setup_unchecked_change{false};
    std::vector<AgentConversationContext> conversation;
    std::vector<AgentAttachmentContext>   attachments;
    std::vector<AgentSkillUse>            skills;
    // The skills the model may read on its own, without their text: the
    // list skill_read's description carries. Empty, and no skill_read.
    std::vector<AgentSkill>               skill_index;
};

struct AgentToolCall
{
    std::string call_id; // provider call ID, opaque outside the service
    ToolRequest request;
    // A live provider normally needs the structured result to continue its
    // response. The deterministic mock keeps its historical one-message
    // behavior and sets this false.
    bool await_result{true};
    // Deterministic mock/test pacing. This is deliberately outside the
    // untrusted ToolRequest and is not part of any public tool contract.
    int test_run_ticks{1};
};

struct AgentToolResult
{
    std::string call_id;
    std::string state;
    std::string output_json;
    std::shared_ptr<const ToolImage> image;
    // Skills this result fires, sent after every result of the response.
    std::vector<AgentSkillUse> skills;
};

enum class AgentEventKind : std::uint8_t { TextDelta, ToolCall, Completed, Failed };

struct AgentEvent
{
    AgentEventKind               kind{AgentEventKind::Completed};
    std::string                  text;
    std::optional<AgentToolCall> tool;
    std::optional<AgentError>    error;

    static AgentEvent delta(std::string value)
    {
        AgentEvent event;
        event.kind = AgentEventKind::TextDelta;
        event.text = std::move(value);
        return event;
    }

    static AgentEvent tool_call(AgentToolCall value)
    {
        AgentEvent event;
        event.kind = AgentEventKind::ToolCall;
        event.tool = std::move(value);
        return event;
    }

    static AgentEvent completed()
    {
        AgentEvent event;
        event.kind = AgentEventKind::Completed;
        return event;
    }

    static AgentEvent failed(AgentError value)
    {
        AgentEvent event;
        event.kind  = AgentEventKind::Failed;
        event.error = std::move(value);
        return event;
    }
};

class IAgentService
{
public:
    virtual ~IAgentService() = default;

    virtual bool ready() const = 0;
    virtual bool busy() const = 0;

    // Starts a user turn. Exactly one turn may be active at a time.
    virtual bool start(const AgentRequest& request) = 0;
    // Continues a provider tool call after the native coordinator reaches a
    // terminal state. The result is data, never authority to execute again.
    virtual bool continue_after_tool(const AgentToolResult& result) = 0;
    virtual void cancel() = 0;

    // Called on the GUI thread. Network-backed services queue worker-thread
    // events internally and release at most one here.
    virtual std::optional<AgentEvent> poll() = 0;
};

using AgentServicePtr = std::unique_ptr<IAgentService>;

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

#include "AgentService.hpp"

#include <nlohmann/json.hpp>

#include <deque>
#include <functional>
#include <memory>
#include <mutex>

namespace Slic3r::GUI::JusPrin::Agent {

struct AgentHttpRequest
{
    std::string url;
    std::string authorization;
    std::string idempotency_key;
    std::string body;
    long        connect_timeout_seconds{10};
    long        request_timeout_seconds{120};
    std::size_t response_size_limit{16u * 1024u * 1024u};
};

struct AgentHttpEvent
{
    enum class Kind { Data, Complete, Error } kind{Kind::Data};
    std::string data;
    std::string error;
    unsigned    status{0};
};

class IAgentHttpTransport
{
public:
    using EventFn = std::function<void(AgentHttpEvent)>;
    virtual ~IAgentHttpTransport() = default;
    virtual bool post(AgentHttpRequest request, EventFn event) = 0;
    virtual void cancel() = 0;
};

// What one request cost, as the provider reported it. `cached_input` is the
// part of `input` the provider served from its prompt cache, and it is the
// number the tool-loading decision rests on: a tools array that stays
// byte-identical across a chat should be cached from the second request on,
// and a catalog that is not being cached is paid for in full every turn.
struct AgentUsage
{
    std::uint64_t input{0};
    std::uint64_t cached_input{0};
    std::uint64_t output{0};
    std::uint64_t total{0};
};

struct OpenAIResponsesConfig
{
    std::string api_key;
    std::string model{"gpt-5.4-mini"};
    std::string endpoint{"https://api.openai.com/v1/responses"};
    std::function<void(const AgentUsage&)> usage_listener;
    // A tool call the adapter refused before it reached a card: the tool
    // name, the arguments as the model sent them, and why.
    std::function<void(const std::string&, const std::string&, const std::string&)> refusal_listener;
};

// Responses API adapter. Network callbacks only append protected input; all
// parsing and AgentEvent delivery happens from poll() on the GUI thread.
class OpenAIResponsesAgent final : public IAgentService
{
public:
    OpenAIResponsesAgent(OpenAIResponsesConfig config, std::unique_ptr<IAgentHttpTransport> transport);
    ~OpenAIResponsesAgent() override;

    bool ready() const override;
    bool busy() const override;
    bool start(const AgentRequest& request) override;
    bool continue_after_tool(const AgentToolResult& result) override;
    void cancel() override;
    std::optional<AgentEvent> poll() override;

private:
    struct QueuedHttpEvent
    {
        std::uint64_t generation{0};
        AgentHttpEvent event;
    };

    // `once` follows the input on this request only and is never kept in
    // the history a continuation is built from.
    bool post(nlohmann::json input, nlohmann::json once = nlohmann::json::array());
    nlohmann::json request_body(nlohmann::json input) const;
    nlohmann::json initial_input(const AgentRequest& request) const;
    void accept_http(std::uint64_t generation, AgentHttpEvent event);
    void parse_available();
    void parse_sse_frame(const std::string& frame);
    void finish_response(const nlohmann::json& response);
    bool next_call();
    void answer_call(const std::string& call_id, const nlohmann::json& output);
    void fail(AgentError error);
    AgentError http_error(unsigned status, const std::string& detail) const;

    OpenAIResponsesConfig                 m_config;
    std::unique_ptr<IAgentHttpTransport>  m_transport;
    mutable std::mutex                    m_mutex;
    std::deque<QueuedHttpEvent>           m_http_events;
    std::deque<AgentEvent>                m_events;
    std::string                           m_sse_buffer;
    nlohmann::json                        m_input_history{nlohmann::json::array()};
    std::string                           m_pending_call_id;
    std::string                           m_pending_tool;
    // A response may hold several calls. They run one at a time, in the
    // order the model wrote them, and every one gets a result; the results
    // go back together in one request once the last has its answer.
    std::deque<nlohmann::json>            m_queued_calls;
    nlohmann::json                        m_call_outputs{nlohmann::json::array()};
    nlohmann::json                        m_call_images{nlohmann::json::array()};
    // The skills the response's results fired, sent after all of them on the
    // next request only; one per name, the latest kept.
    std::vector<AgentSkillUse>            m_call_skills;
    // The first call of this response that did not succeed, as "tool
    // (call_id)"; every call after it is answered without being run.
    std::string                           m_failed_call;
    std::string                           m_request_id;
    unsigned                              m_request_sequence{0};
    unsigned                              m_rejected_calls{0};
    std::uint64_t                         m_http_generation{0};
    bool                                  m_busy{false};
    bool                                  m_waiting_for_tool{false};
    bool                                  m_terminal_seen{false};
    bool                                  m_allow_import{false};
    // The skills skill_read lists; the tool is offered only with some.
    std::vector<AgentSkill>               m_skill_index;
    bool                                  m_title_request{false};
    // The instructions and tools of the conversation this turn belongs to.
    AgentSessionProfile                   m_session;
};

std::unique_ptr<IAgentHttpTransport> make_openai_http_transport();

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

#include "AgentService.hpp"
#include "AgentSetup.hpp"

#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Agent {

struct AgentRuntime
{
    AgentServicePtr      service;
    AgentAvailability    availability{AgentAvailability::Unavailable};
    std::string          provider;
    std::string          unavailable_reason;
    // Verifies and stores credentials entered in the Agent dock. Always
    // present: setup is what an unconfigured build offers.
    AgentSetupServicePtr setup;
};

// Reads the Agent's choices and provider key from AppConfig. Project/recovery
// state never receives credentials.
AgentRuntime load_agent_runtime(AppConfig* config);

// Shared provider credential lookup for bounded, non-conversational features
// such as printer recognition. The key is an AppConfig item, "<provider>_api_key"
// in the Agent section, rather than an OS credential-store entry: macOS asks
// for the login password whenever a differently signed build reads a Keychain
// entry, which every unsigned rebuild is.
std::string load_provider_api_key(const AppConfig* config, const std::string& provider);

// The setup service the Agent dock drives: it verifies a candidate key
// against the live provider and, on success, stores it and records the
// non-secret choices load_agent_runtime() reads on the next launch.
AgentSetupServicePtr make_agent_setup(AppConfig* config);

} // namespace Slic3r::GUI::JusPrin::Agent
#include "AgentConfiguration.hpp"

#include "OpenAIResponsesAgent.hpp"
#include "libslic3r/AppConfig.hpp"

#include <boost/log/trivial.hpp>

#include <cstdlib>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

constexpr const char* kSection = "jusprin_agent";

std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }

bool configured_true(const AppConfig* config, const char* key)
{
    if (config == nullptr)
        return false;
    const std::string value = config->get(kSection, key);
    return value == "true" || value == "1";
}

} // namespace

std::string load_provider_api_key(const AppConfig* config, const std::string& provider)
{
    return config == nullptr ? std::string() : config->get(kSection, api_key_item_for(provider));
}

AgentRuntime load_agent_runtime(AppConfig* config)
{
    AgentRuntime runtime;
    runtime.setup = make_agent_setup(config);
    runtime.provider = config == nullptr ? std::string() : config->get(kSection, "provider");
    if (runtime.provider.empty())
        runtime.provider = "openai";

    if (!configured_true(config, "enabled")) {
        runtime.unavailable_reason = "The Agent is not enabled.";
        return runtime;
    }
    if (runtime.provider != "openai") {
        runtime.unavailable_reason = "The configured Agent provider is not supported.";
        return runtime;
    }
    if (!configured_true(config, "cloud_consent")) {
        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
        return runtime;
    }

    OpenAIResponsesConfig openai;
    openai.api_key = load_provider_api_key(config, runtime.provider);
    if (config != nullptr && !config->get(kSection, "model").empty())
        openai.model = config->get(kSection, "model");
    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
        openai.endpoint = endpoint;
    // Refused tool calls never reach a card or the activity list; the log is
    // where a wrong call can be read afterwards.
    openai.refusal_listener = [](const std::string& tool, const std::string& arguments, const std::string& code) {
        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
    };
    if (openai.api_key.empty()) {
        runtime.unavailable_reason = "No OpenAI API key is configured.";
        return runtime;
    }
    runtime.service = std::make_unique<OpenAIResponsesAgent>(std::move(openai), make_openai_http_transport());
    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
    if (runtime.availability == AgentAvailability::Unavailable)
        runtime.unavailable_reason = "The OpenAI Agent could not be initialized.";
    return runtime;
}

AgentSetupServicePtr make_agent_setup(AppConfig* config)
{
    // Committing is the only part of setup that touches the machine, so it
    // lives here rather than in the GUI-free probe. Reaching this point means
    // the user read what the dock says about the provider billing them and
    // about the key staying on this machine, and chose to continue: that is
    // the cloud consent load_agent_runtime() requires on the next launch.
    auto commit = [config](const SetupCredentials& credentials) {
        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
            return false;
        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
        config->set(kSection, "provider", credentials.provider);
        config->set(kSection, "enabled", "true");
        config->set(kSection, "cloud_consent", "true");
        if (!credentials.model.empty())
            config->set(kSection, "model", credentials.model);
        // Written now, not at the next routine save, so a crash after setup
        // does not lose a key the user was just told is stored.
        config->save();
        return true;
    };
    std::string endpoint_override;
    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
        endpoint_override = endpoint;
    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit),
                                              std::move(endpoint_override));
}

} // namespace Slic3r::GUI::JusPrin::Agent
#include "OpenAIResponsesAgent.hpp"

#include "slic3r/Utils/Http.hpp"

#include <memory>
#include <mutex>
#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

class OpenAIHttpTransport final : public IAgentHttpTransport
{
public:
    bool post(AgentHttpRequest request, EventFn event) override
    {
        cancel();
        auto state = std::make_shared<State>();
        state->event = std::move(event);
        m_state = state;

        auto http = Slic3r::Http::post(std::move(request.url));
        http.header("Authorization", request.authorization)
            .header("Idempotency-Key", request.idempotency_key)
            .header("Content-Type", "application/json")
            .header("Accept", "text/event-stream")
            .tls_verify(true)
            .timeout_connect(request.connect_timeout_seconds)
            .timeout_max(request.request_timeout_seconds)
            .size_limit(request.response_size_limit)
            .set_post_body(request.body)
            .on_progress([weak = std::weak_ptr<State>(state)](Slic3r::Http::Progress progress, bool& should_cancel) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                should_cancel = locked->cancelled;
                if (locked->cancelled || progress.buffer.size() <= locked->seen)
                    return;
                std::string delta = progress.buffer.substr(locked->seen);
                locked->seen = progress.buffer.size();
                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, std::move(delta), {}, 0});
            })
            .on_complete([weak = std::weak_ptr<State>(state)](std::string body, unsigned status) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                if (locked->cancelled)
                    return;
                if (body.size() > locked->seen)
                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, body.substr(locked->seen), {}, status});
                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Complete, {}, {}, status});
            })
            .on_error([weak = std::weak_ptr<State>(state)](std::string, std::string error, unsigned status) {
                const auto locked = weak.lock();
                if (!locked)
                    return;
                std::lock_guard<std::mutex> guard(locked->mutex);
                if (!locked->cancelled)
                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Error, {}, std::move(error), status});
            });
        state->http = http.perform();
        return state->http != nullptr;
    }

    void cancel() override
    {
        const auto state = std::move(m_state);
        if (!state)
            return;
        Slic3r::Http::Ptr http;
        {
            std::lock_guard<std::mutex> guard(state->mutex);
            state->cancelled = true;
            http = state->http;
        }
        if (http)
            http->cancel();
    }

private:
    struct State
    {
        std::mutex       mutex;
        EventFn          event;
        Slic3r::Http::Ptr http;
        std::size_t      seen{0};
        bool             cancelled{false};
    };
    std::shared_ptr<State> m_state;
};

} // namespace

std::unique_ptr<IAgentHttpTransport> make_openai_http_transport()
{
    return std::make_unique<OpenAIHttpTransport>();
}

